import numpy as np
def equation(t, A, params):
    p=params
    return p[0]*np.exp(-p[1]*t) + p[2]*A**p[3]*np.exp(-p[4]*t) + p[5]*A + p[6]*A**2*np.exp(-p[7]*t)

def fit(tp,ap):
    cols=[t**i*A**j for i in range(tp+1) for j in range(ap+1)]
    X=np.column_stack(cols)
    c=np.linalg.lstsq(X,dA_dt,rcond=None)[0]
    r=dA_dt-X@c
    return np.mean(r**2)/np.var(dA_dt)
for tp in [1,2,3,4]:
    print(tp,[float('%.3g'%fit(tp,ap)) for ap in [1,2,3,4]])
